  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-276', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('14314a8100d3efbaaa1cee0705bd5aef'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"earthy_herbal","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":4,"heat":1,"pungency":2,"richness":3,"freshness":3,"intensity":4},"dominant_flavors":["terreux","herbacé","savoureux"],"aroma_families":["ail","oignon_compoté","laurier","fumé","haricot_noir","porc_fumé","orange"],"target_textures":["bouillon_épais","haricots_crémeux","viandes_tendres"],"signature_ingredients":["Haricot noir sec","Épaule de porc salée","Poitrine de porc fumée","Saucisse linguiça"],"identity_guardrails":["haricot_noir","mélange_de_porcs","accompagnements_complets"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
